func astNode(v any) *Node    { n, _ := v.(*Node); return n }
func astInt(v any) int       { i, _ := v.(int); return i }
func astString(v any) string { s, _ := v.(string); return s }
func astBool(v any) bool     { x, _ := v.(bool); return x }
func astPtrInt(v any) *int {
	if i, ok := v.(int); ok {
		return &i
	}
	return nil
}
func astPtrString(v any) *string {
	if s, ok := v.(string); ok {
		return &s
	}
	return nil
}
func astPtrBool(v any) *bool {
	if x, ok := v.(bool); ok {
		return &x
	}
	return nil
}

// astChunk owns unused values and the next allocation size for one type.
// Handed-out values are never reused, even when a parse discards them.
type astChunk[T any] struct {
	free []T
	next int
}

// grow starts small and doubles up to limit. The request is always satisfied.
func (s *astChunk[T]) grow(n, initial, limit int) {
	size := s.next
	if size == 0 {
		size = initial
	}
	for size < n {
		size *= 2
	}
	s.free = make([]T, size)
	s.next = size * 2
	if s.next > limit {
		s.next = limit
	}
}

// astNew returns a new zero value from a chunk that grows from 8 to 256 values.
func astNew[T any](s *astChunk[T]) *T {
	if len(s.free) == 0 {
		s.grow(1, 8, 256)
	}
	v := &s.free[0]
	s.free = s.free[1:]
	return v
}

// astSlice returns n zero values with capacity n, so appending cannot overwrite
// another returned slice. Small-list chunks grow from 64 to 1,024 elements.
func astSlice[T any](s *astChunk[T], n int) []T {
	if n == 0 {
		return []T{} // an empty list, not nil
	}
	if n > 256 {
		return make([]T, n)
	}
	if len(s.free) < n {
		s.grow(n, 64, 1024)
	}
	v := s.free[:n:n]
	s.free = s.free[n:]
	return v
}

func (a *astConv) toMatch(n *Node) *Match {
	if n == nil || n.Type() != "Match" {
		return nil
	}
	v := astNew(&a.match)
	*v = Match{Span: Span{int(n.Start), int(n.End)}, Text: n.Text}
	return v
}

func (a *astConv) toError(n *Node) *Error {
	if n == nil || n.Type() != "Error" {
		return nil
	}
	msg, _ := n.Field("message").(string)
	v := astNew(&a.error)
	*v = Error{Span: Span{int(n.Start), int(n.End)}, Text: n.Text, Message: msg}
	return v
}

// anyValue converts a value of a statically unknown type into the typed value of its type (CST
// nodes stay *Node).
func (a *astConv) anyValue(v any) any {
	n, ok := v.(*Node)
	if !ok || n == nil {
		return v
	}
	switch n.Type() {
	case "Match":
		return a.toMatch(n)
	case "Error":
		return a.toError(n)
	case "Bool":
		return a.toBool(n)
	case "Ident":
		return a.toIdent(n)
	case "Number":
		return a.toNumber(n)
	case "String":
		return a.toString(n)
	case "ArrayLit":
		return a.toArrayLit(n)
	case "Assign":
		return a.toAssign(n)
	case "Binary":
		return a.toBinary(n)
	case "Block":
		return a.toBlock(n)
	case "Call":
		return a.toCall(n)
	case "Cond":
		return a.toCond(n)
	case "ExprStmt":
		return a.toExprStmt(n)
	case "Func":
		return a.toFunc(n)
	case "If":
		return a.toIf(n)
	case "Index":
		return a.toIndex(n)
	case "Let":
		return a.toLet(n)
	case "Member":
		return a.toMember(n)
	case "Program":
		return a.toProgram(n)
	case "Return":
		return a.toReturn(n)
	case "Unary":
		return a.toUnary(n)
	case "While":
		return a.toWhile(n)
	}
	return n
}

