	switch n.Type() {
	case "Error":
		return a.toError(n)
	case "Ident":
		return a.toIdent(n)
	case "Number":
		return a.toNumber(n)
	case "String":
		return a.toString(n)
	case "Bool":
		return a.toBool(n)
	case "Binary":
		return a.toBinary(n)
	case "Unary":
		return a.toUnary(n)
	case "Call":
		return a.toCall(n)
	case "Index":
		return a.toIndex(n)
	case "Member":
		return a.toMember(n)
	case "Cond":
		return a.toCond(n)
	case "ArrayLit":
		return a.toArrayLit(n)
	}
	return nil
